func hooksRootForInstall(hooksDir string) (*os.Root, error) {
	abs, err := absHooksDir(hooksDir)
	if err != nil {
		return nil, err
	}
	info, err := os.Lstat(abs)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve os.IsNotExist classification
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", abs, osroot.ErrSymlinkedPath)
	}
	return osroot.Shared(abs) //nolint:wrapcheck // preserve os.IsNotExist classification, as the doc comment promises
}

func validateEffectiveHooksRoot(hooks effectiveHooksRoot) (effectiveHooksRoot, error) {
	info, err := osroot.LstatNoSymlinks(hooks.root, hooks.prefix)
	if os.IsNotExist(err) {
		return hooks, nil
	}
	if err != nil {
		return effectiveHooksRoot{}, fmt.Errorf("inspect effective hooks directory %s: %w", hooks.path, err)
	}
	if !info.IsDir() {
		return effectiveHooksRoot{}, fmt.Errorf("effective hooks path %s is not a real directory", hooks.path)
	}
	return hooks, nil
}
